let boxShadowLayerCount = 0;function addBoxShadowLayer(){const id = boxShadowLayerCount++;const wrap = document.createElement("div");wrap.className = "tool-workspace";wrap.style.flexWrap = "wrap";wrap.style.marginBottom = "0.5rem";wrap.dataset.layerId = id;wrap.innerHTML = `
    <label style="font-size:0.8rem; color:var(--phosphor-dim-text);">x <input type="range" min="-40" max="40" value="0" oninput="renderBoxShadow()" class="bs-x" style="width:70px;"></label>
    <label style="font-size:0.8rem; color:var(--phosphor-dim-text);">y <input type="range" min="-40" max="40" value="10" oninput="renderBoxShadow()" class="bs-y" style="width:70px;"></label>
    <label style="font-size:0.8rem; color:var(--phosphor-dim-text);">blur <input type="range" min="0" max="80" value="20" oninput="renderBoxShadow()" class="bs-blur" style="width:70px;"></label>
    <label style="font-size:0.8rem; color:var(--phosphor-dim-text);">spread <input type="range" min="-20" max="40" value="0" oninput="renderBoxShadow()" class="bs-spread" style="width:70px;"></label>
    <input type="color" class="bs-color" value="#000000" oninput="renderBoxShadow()">
    <label style="font-size:0.8rem; color:var(--phosphor-dim-text);">opacity <input type="range" min="0" max="100" value="35" oninput="renderBoxShadow()" class="bs-opacity" style="width:60px;"></label>
    <label style="font-size:0.8rem; color:var(--phosphor-dim-text);"><input type="checkbox" class="bs-inset" onchange="renderBoxShadow()"> inset</label>
    <button onclick="removeBoxShadowLayer(${id})">&times;</button>
  `;document.getElementById("boxshadow-layers").appendChild(wrap);renderBoxShadow();}function removeBoxShadowLayer(id){document.querySelector(`[data-layer-id="${id}"]`)?.remove();renderBoxShadow();}function hexToRgbStr(hex){const clean = hex.replace("#", "");return `${parseInt(clean.slice(0, 2), 16)}, ${parseInt(clean.slice(2, 4), 16)}, ${parseInt(clean.slice(4, 6), 16)}`;}function renderBoxShadow(){const layers = [...document.querySelectorAll("#boxshadow-layers .tool-workspace")];const shadowValues = layers.map((row) =>{const x = row.querySelector(".bs-x").value;const y = row.querySelector(".bs-y").value;const blur = row.querySelector(".bs-blur").value;const spread = row.querySelector(".bs-spread").value;const color = row.querySelector(".bs-color").value;const opacity = row.querySelector(".bs-opacity").value / 100;const inset = row.querySelector(".bs-inset").checked ? "inset " : "";return `${inset}${x}px ${y}px ${blur}px ${spread}px rgba(${hexToRgbStr(color)}, ${opacity})`;});const cssValue = shadowValues.join(",\n  ");document.getElementById("boxshadow-preview").style.boxShadow = shadowValues.join(", ");document.getElementById("boxshadow-css").textContent = shadowValues.length ? `box-shadow: ${cssValue};` : "// add at least one shadow layer";}document.addEventListener("DOMContentLoaded", () => addBoxShadowLayer());